(function(){
'use strict';
const $=(s,r=document)=>r.querySelector(s);
const API='/api/livestock';
const PIG='Lợn';
const DOG='Chó';
const PIG_GROUPS=['PIG_SOW','PIGLET','PIG_MEAT'];
const PIG_LEGACY_GROUPS=['UNCLASSIFIED','PIG_BOAR'];
const DOG_GROUPS=['DOG_GUARD','DOG_PET','DOG_OTHER'];
const state={page:1,pageSize:20,search:'',area_code:'',facility_type:'',animal_type:'',animal_group:'',status:'',vaccinated:'',has_pig_sow:'',has_pig_meat:'',sort:'household_code',direction:'ASC',catalogs:null,selectedHousehold:null,householdSuggestions:[],drawerHousehold:null,currentHouseholdId:null,detailReturn:null};
const labels={noData:'Chưa có dữ liệu chăn nuôi',total:'Tổng số',records:'cơ sở',animal:'con',unknown:'Chưa cập nhật',loading:'Đang tải...',permission:'Tài khoản hiện tại không có quyền thực hiện thao tác này'};
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function num(v){return new Intl.NumberFormat('vi-VN').format(Number(v||0));}
function toast(msg,type='success'){ if(typeof showToast==='function') showToast(msg,type); else console[type==='danger'?'error':'log'](msg); }
function can(module,action){const role=(window.App?.user?.role||'').toUpperCase(); if(['SUPER_ADMIN','ADMIN'].includes(role))return true; if(role==='OFFICER')return module==='livestock'&&['read','create','update'].includes(action); if(role==='VIEWER')return module==='livestock'&&action==='read'; return true;}
function openModal(id){return window.TenantAppPlatform?.modals?.open?.(id)||window.bootstrap?.Modal?.getOrCreateInstance?.($('#'+id))?.show();}
function closeModal(id){return window.TenantAppPlatform?.modals?.close?.(id)||window.bootstrap?.Modal?.getOrCreateInstance?.($('#'+id))?.hide();}
async function request(url,options={}){ if(typeof api==='function')return api(url,options); const token=window.App?.token||localStorage.getItem(tenantStorageKey('token'))||''; const init={method:options.method||'GET',headers:{Accept:'application/json',Authorization:token?'Bearer '+token:''}}; if(options.body){init.headers['Content-Type']='application/json';init.body=JSON.stringify(options.body);} const res=await fetch(url,init); const json=await res.json().catch(()=>null); if(!res.ok||json?.ok===false)throw new Error(json?.error?.message||json?.message||'Không tải được dữ liệu'); return json?.data??json;}
function debounce(fn,ms){let t;return function(){clearTimeout(t);t=setTimeout(()=>fn.apply(this,arguments),ms);};}
document.addEventListener('DOMContentLoaded',init);
document.addEventListener('tenant:screen-change',e=>{if(e.detail?.screen==='livestock')load();});
function init(){
window.TenantAppPlatform?.modals?.registerBootstrap?.('livestockModal','#livestockModal');
window.TenantAppPlatform?.modals?.registerBootstrap?.('livestockHouseholdModal','#livestockHouseholdModal');
$('#livestockForm')?.addEventListener('submit',save);
$('#livestockModal')?.addEventListener('hidden.bs.modal',restoreHouseholdDetailAfterForm);
$('#livestockSearch')?.addEventListener('input',debounce(()=>{state.search=$('#livestockSearch').value.trim();state.page=1;load();},300));
[['livestockAreaFilter','area_code'],['livestockFacilityTypeFilter','facility_type'],['livestockAnimalTypeFilter','animal_type'],['livestockAnimalGroupFilter','animal_group'],['livestockStatusFilter','status'],['livestockPigSowFilter','has_pig_sow'],['livestockPigMeatFilter','has_pig_meat']].forEach(([id,key])=>$('#'+id)?.addEventListener('change',e=>{state[key]=e.target.value;normalizeFilterDependencies();state.page=1;load();}));
$('#livestockPageSize')?.addEventListener('change',e=>{state.pageSize=Number(e.target.value||20);state.page=1;load();});
$('#livestockHouseholdAutocomplete')?.addEventListener('input',debounce(searchHouseholds,250));
document.addEventListener('pointerdown',event=>{if(!event.target.closest('#livestockHouseholdSuggestions')&&event.target.id!=='livestockHouseholdAutocomplete')hideSuggestions();});
registerActions(); installHouseholdDetailHook(); if($('#livestockScreen')?.classList.contains('active'))load();
}
function registerActions(){const a=window.TenantAppPlatform?.actions; if(!a?.register)return; a.register('livestock.openCreate',()=>openForm()); a.register('livestock.search',()=>{state.search=$('#livestockSearch')?.value.trim()||'';state.page=1;load();}); a.register('livestock.reset',resetFilters); a.register('livestock.page',ctx=>{state.page=Number(ctx.dataset.page||1);load();}); a.register('livestock.sort',ctx=>sortBy(ctx.dataset.livestockSort)); a.register('livestock.selectHousehold',ctx=>selectHousehold(state.householdSuggestions.find(x=>String(x.id)===ctx.dataset.id))); a.register('livestock.household',ctx=>openDrawer(Number(ctx.dataset.householdId||ctx.dataset.id||0))); a.register('livestock.create',ctx=>openFormFromAction(ctx,null,{id:Number(ctx.dataset.householdId||ctx.dataset.id||0),household_code:ctx.dataset.householdCode||'',head_citizen_name:ctx.dataset.headCitizenName||'',address:ctx.dataset.address||''})); a.register('livestock.edit',ctx=>openFormFromAction(ctx,Number(ctx.dataset.id||0))); a.register('livestock.delete',ctx=>remove(Number(ctx.dataset.id||0))); a.register('livestock.addGroup',()=>addGroupRow()); a.register('livestock.removeGroup',ctx=>{const row=ctx.closest('.livestock-group-row'); row?.remove(); updateGroupRemoveButtons();}); a.register('livestock.kpi',ctx=>{Object.assign(state,{animal_type:'',animal_group:'',facility_type:'',vaccinated:'',has_pig_sow:'',has_pig_meat:''}); const f=ctx.dataset.filter; if(f==='pig')state.animal_type=PIG; if(f==='pig_sow')state.animal_group='PIG_SOW'; if(f==='pig_meat')state.animal_group='PIG_MEAT'; if(f==='piglet')state.animal_group='PIGLET'; if(f==='dog')state.animal_type=DOG; if(f==='dog_vaccinated'){state.animal_type=DOG;state.vaccinated='1';} if(f==='dog_unrecorded'){state.animal_type=DOG;state.vaccinated='0';} if(f==='farm')state.facility_type='FARM'; if(f==='pig_farm'){state.animal_type=PIG;state.facility_type='FARM';} state.page=1;load();}); a.bind?.(document);}
async function ensureCatalogs(){ if(state.catalogs)return state.catalogs; state.catalogs=await request(API+'/catalogs',{cacheTtl:60000}); fill('#livestockAnimalTypeFilter',state.catalogs.animal_types,'Tất cả'); fill('#livestockFacilityTypeFilter',state.catalogs.facility_types,'Tất cả'); fill('#livestockAnimalGroupFilter',state.catalogs.animal_groups,'Tất cả'); fill('#livestockFacilityTypeSelect',state.catalogs.facility_types,'Chọn loại hình'); fill('#livestockAnimalTypeSelect',state.catalogs.animal_types,'Chọn loại vật nuôi'); fill('#livestockDiseaseSelect',state.catalogs.disease_statuses,'Chọn tình trạng'); fill('#livestockStatusSelect',state.catalogs.statuses,'Chọn trạng thái'); fill('#livestockAreaFilter',state.catalogs.areas,'Tất cả'); syncFilterControls(); return state.catalogs; }
function fill(sel,items,first){const el=$(sel); if(!el)return; el.innerHTML='<option value="">'+esc(first)+'</option>'+(items||[]).map(i=>'<option value="'+esc(i.value)+'">'+esc(i.label||i.value)+'</option>').join('');}
const FILTER_KEYS=['search','area_code','facility_type','animal_type','animal_group','status','vaccinated','has_pig_sow','has_pig_meat'];
const FILTER_CONTROLS={search:'livestockSearch',area_code:'livestockAreaFilter',facility_type:'livestockFacilityTypeFilter',animal_type:'livestockAnimalTypeFilter',animal_group:'livestockAnimalGroupFilter',status:'livestockStatusFilter',has_pig_sow:'livestockPigSowFilter',has_pig_meat:'livestockPigMeatFilter'};
function validGroupForType(group,type){if(!group)return ''; if(!type)return group; const allowed=type===PIG?PIG_GROUPS.concat(PIG_LEGACY_GROUPS):(type===DOG?DOG_GROUPS:[]); return allowed.includes(group)?group:'';}
function filterGroupOptions(){const items=state.catalogs?.animal_groups||[]; if(!state.animal_type)return items; const allowed=state.animal_type===PIG?PIG_GROUPS.concat(PIG_LEGACY_GROUPS):(state.animal_type===DOG?DOG_GROUPS:[]); const values=new Set(allowed); return items.filter(i=>values.has(String(i.value)));}
function normalizeFilterDependencies(){state.animal_group=validGroupForType(String(state.animal_group||''),state.animal_type); if(state.animal_type&&state.animal_type!==PIG){state.has_pig_sow='';state.has_pig_meat='';}}
function syncFilterControls(){normalizeFilterDependencies(); const group=$('#livestockAnimalGroupFilter'); if(group){const value=state.animal_group||''; fill('#livestockAnimalGroupFilter',filterGroupOptions(),'Tất cả'); group.value=value;} Object.entries(FILTER_CONTROLS).forEach(([key,id])=>{const el=$('#'+id); if(el&&el.value!==String(state[key]||''))el.value=state[key]||'';});}
function filterState(){return FILTER_KEYS.reduce((out,key)=>{out[key]=state[key]||'';return out;},{});}
function optionList(items,first='Tất cả'){return [{label:first,value:''}].concat((items||[]).map(i=>({label:i.label||i.value,value:i.value}))); }
function mobileFilterDefinition(){const catalogs=state.catalogs||{}; return {supportsCombinedFilter:true,fields:[
{key:'search',label:'Từ khóa',type:'search',placeholder:'Mã hộ, chủ hộ, loại, giống, địa chỉ...'},
{key:'area_code',label:'Khu vực/xóm cũ',type:'select',options:optionList(catalogs.areas)},
{key:'facility_type',label:'Loại hình',type:'select',options:optionList(catalogs.facility_types)},
{key:'animal_type',label:'Loại vật nuôi',type:'select',options:optionList(catalogs.animal_types)},
{key:'animal_group',label:'Nhóm vật nuôi',type:'select',options:optionList(filterGroupOptions())},
{key:'status',label:'Trạng thái',type:'select',options:optionList(catalogs.statuses,'Tất cả trạng thái')},
{key:'vaccinated',label:'Tiêm phòng',type:'select',options:[{label:'Tất cả',value:''},{label:'Đã tiêm',value:'1'},{label:'Chưa ghi nhận',value:'0'}]},
{key:'has_pig_sow',label:'Lợn nái',type:'select',options:[{label:'Tất cả',value:''},{label:'Có lợn nái',value:'1'}]},
{key:'has_pig_meat',label:'Lợn thịt',type:'select',options:[{label:'Tất cả',value:''},{label:'Có lợn thịt',value:'1'}]}
]};}
function applyMobileFilters(filters={}){FILTER_KEYS.forEach(key=>{state[key]=String(filters[key]||'');}); normalizeFilterDependencies(); state.page=1; syncFilterControls(); return load();}
function registerMobileFilterAdapter(){const registry=window.TenantAppMobileFilterAdapters=window.TenantAppMobileFilterAdapters||{}; const adapter={isReady(){return !!state.catalogs;},ensureReady:ensureCatalogs,getState:filterState,getDefinition:mobileFilterDefinition,applyFilters:applyMobileFilters,reset:resetFilters,reload:load,setPage(page){state.page=Number(page||1);return load();},queryString(){return params().toString();}}; registry.livestock=adapter; registry.livestockScreen=adapter;}
registerMobileFilterAdapter();
function params(){const p=new URLSearchParams({page:state.page,pageSize:state.pageSize,sort:state.sort,direction:state.direction}); ['search','area_code','facility_type','animal_type','animal_group','status','vaccinated','has_pig_sow','has_pig_meat'].forEach(k=>{if(state[k])p.set(k,state[k]);}); return p;}
async function load(){if(!can('livestock','read'))return; await ensureCatalogs(); syncFilterControls(); try{const data=await request(API+'?'+params().toString(),{cacheTtl:0}); renderRows(data); renderPager(data); renderDashboard();}catch(e){toast(e.message,'danger');}}
function renderRows(data){const host=$('#livestockRows'); if(!host)return; const items=data.items||[]; $('#livestockTotalCount')&&($('#livestockTotalCount').textContent=labels.total+': '+num(data.total||0)+' '+labels.records); host.innerHTML=items.length?items.map((r,i)=>rowHtml(r,(Number(data.page||1)-1)*Number(data.pageSize||state.pageSize)+i+1)).join(''):'<tr><td colspan="9" class="text-center text-muted py-4">'+labels.noData+'</td></tr>'; window.TenantAppSyncResponsiveTableLabels?.($('#livestockScreen')||document);}
function groupQuantity(r,group){return (r.groups||[]).filter(g=>g.animal_group===group).reduce((sum,g)=>sum+Number(g.quantity||0),0);}
function displayQuantity(r){if(state.animal_group)return groupQuantity(r,state.animal_group); if(state.animal_type===PIG)return Number(r.pig_total||0); if(state.animal_type===DOG)return Number(r.dog_total||0); return Number(r.total_quantity||0);}
function rowHtml(r,idx){const groups=(r.groups||[]).map(g=>esc(g.group_label)+': '+num(g.quantity)).join('<br>'); const qty=displayQuantity(r); return '<tr><td data-label="STT">'+idx+'</td><td data-label="Hộ/Chủ cơ sở"><button class="btn btn-link p-0" type="button" data-platform-action="livestock.household" data-household-id="'+Number(r.household_id)+'">'+esc(r.owner_name||r.head_citizen_name)+'</button><div class="text-muted small">'+esc(r.household_code||'')+'</div></td><td data-label="Loại hình">'+esc(r.facility_type_label)+'</td><td data-label="Tên cơ sở">'+esc(r.facility_name||'')+'</td><td data-label="Vật nuôi">'+esc(r.animal_summary||'')+'<div class="small text-muted">'+groups+'</div></td><td data-label="Tổng đàn"><strong>'+num(qty)+'</strong> con</td><td data-label="Địa điểm">'+esc(r.location||r.address||'')+'</td><td data-label="Trạng thái">'+esc(r.status_label||'')+'</td><td data-label="Thao tác" class="text-end"><button class="btn btn-sm btn-outline-secondary" type="button" data-platform-action="livestock.household" data-household-id="'+Number(r.household_id)+'"><i class="fa-solid fa-eye"></i></button> '+(can('livestock','update')?'<button class="btn btn-sm btn-outline-primary" type="button" data-platform-action="livestock.edit" data-id="'+Number(r.id)+'"><i class="fa-solid fa-pen-to-square"></i></button> ':'')+(can('livestock','delete')?'<button class="btn btn-sm btn-outline-danger" type="button" data-platform-action="livestock.delete" data-id="'+Number(r.id)+'"><i class="fa-solid fa-trash"></i></button>':'')+'</td></tr>';}
function renderPager(data){const host=$('#livestockPager'); if(!host)return; const page=Number(data.page||1),totalPages=Number(data.totalPages||1),pages=[]; for(let i=Math.max(1,page-2);i<=Math.min(totalPages,page+2);i++)pages.push(i); host.innerHTML='<button class="btn btn-sm btn-outline-secondary" '+(page<=1?'disabled':'')+' data-platform-action="livestock.page" data-page="'+(page-1)+'">Trước</button>'+pages.map(p=>'<button class="btn btn-sm '+(p===page?'btn-primary':'btn-outline-secondary')+'" data-platform-action="livestock.page" data-page="'+p+'">'+p+'</button>').join('')+'<button class="btn btn-sm btn-outline-secondary" '+(page>=totalPages?'disabled':'')+' data-platform-action="livestock.page" data-page="'+(page+1)+'">Sau</button>';}
async function renderDashboard(){const host=$('#livestockMiniDashboard'); if(!host)return; try{const data=await request(API+'/dashboard?'+params().toString(),{cacheTtl:0}); const m=data.metrics||{}; const cards=[['Tổng hộ có chăn nuôi',m.livestock_households,'hộ','fa-house','green','households'],['Tổng cơ sở chăn nuôi',m.facility_total,'cơ sở','fa-warehouse','blue','facilities'],['Tổng trang trại',m.farm_total,'trang trại','fa-industry','orange','farm'],['Tổng đàn vật nuôi',m.livestock_total,'con','fa-paw','blue','all'],['Tổng đàn lợn',m.pig_total,'con','fa-bacon','purple','pig'],['Lợn nái',m.pig_sow_total,'con','fa-circle-dot','green','pig_sow'],['Lợn con theo mẹ',m.piglet_total,'con','fa-circle-dot','cyan','piglet'],['Lợn thịt',m.pig_meat_total,'con','fa-circle-dot','orange','pig_meat'],['Hộ nuôi lợn',m.pig_households,'hộ','fa-house-chimney','green','pig'],['Trang trại nuôi lợn',m.pig_farms,'trang trại','fa-warehouse','purple','pig_farm'],['Tổng đàn chó',m.dog_total,'con','fa-dog','blue','dog'],['Hộ nuôi chó',m.dog_households,'hộ','fa-house-chimney','green','dog'],['Chó đã tiêm phòng',m.dog_vaccinated_total,'con','fa-syringe','purple','dog_vaccinated'],['Chưa ghi nhận tiêm phòng',m.dog_unrecorded_vaccination_total,'con','fa-clipboard-question','orange','dog_unrecorded']]; host.innerHTML=cards.map(c=>'<article class="livestock-kpi-card tone-'+c[4]+'" role="button" tabindex="0" data-platform-action="livestock.kpi" data-filter="'+c[5]+'"><span><i class="fa-solid '+c[3]+'"></i></span><div><p>'+esc(c[0])+'</p><strong>'+num(c[1])+'</strong><em>'+esc(c[2])+'</em></div></article>').join('');}catch(e){host.innerHTML='';}}
function resetFilters(){Object.assign(state,{page:1,search:'',area_code:'',facility_type:'',animal_type:'',animal_group:'',status:'',vaccinated:'',has_pig_sow:'',has_pig_meat:''}); ['livestockSearch','livestockAreaFilter','livestockFacilityTypeFilter','livestockAnimalTypeFilter','livestockAnimalGroupFilter','livestockStatusFilter','livestockPigSowFilter','livestockPigMeatFilter'].forEach(id=>{const el=$('#'+id);if(el)el.value='';}); load();}
function sortBy(key){if(!key)return; if(state.sort===key)state.direction=state.direction==='ASC'?'DESC':'ASC'; else{state.sort=key;state.direction='ASC';} load();}
function waitForModalHidden(id){const modal=$('#'+id); if(!modal||!modal.classList.contains('show'))return Promise.resolve(); return new Promise(resolve=>{let done=false; const finish=()=>{if(done)return; done=true; resolve();}; modal.addEventListener('hidden.bs.modal',finish,{once:true}); closeModal(id); setTimeout(finish,700);});}
async function openFormFromAction(ctx,id=null,household=null){const detailModal=ctx?.target?.closest?.('#detailModal'); if(detailModal?.classList.contains('show')){state.detailReturn={householdId:Number(household?.id||ctx.dataset.householdId||state.currentHouseholdId||0)}; await waitForModalHidden('detailModal');} return openForm(id,household);}
async function restoreHouseholdDetailAfterForm(){const detail=state.detailReturn; if(!detail)return; state.detailReturn=null; if(detail.householdId&&typeof window.showHousehold==='function')await window.showHousehold(detail.householdId);}
async function openForm(id=null,household=null){ if(!can('livestock',id?'update':'create'))return toast(labels.permission,'warning'); await ensureCatalogs(); const form=$('#livestockForm'); if(!form)return; form.reset(); form.elements.id.value=''; form.elements.household_id.value=''; state.selectedHousehold=null; $('#livestockHouseholdAutocomplete').disabled=!!id||!!household; $('#livestockHouseholdAutocomplete').value=''; $('#livestockHouseholdSelected').textContent=''; const groupHost=$('#livestockGroupRows'); if(groupHost)groupHost.innerHTML=''; hideSuggestions(); if(household)selectHousehold(household,true); if(id){const row=await request(API+'/'+encodeURIComponent(id)); setForm(row);} else if(groupHost)addGroupRow({animal_type:PIG,animal_group:'',quantity:0}); openModal('livestockModal');}
async function searchHouseholds(){const input=$('#livestockHouseholdAutocomplete'),host=$('#livestockHouseholdSuggestions'); if(!input||!host)return; const q=input.value.trim(); state.selectedHousehold=null; state.householdSuggestions=[]; $('#livestockForm').elements.household_id.value=''; if(q.length<2){hideSuggestions();return;} const data=await request(API+'/household-search?q='+encodeURIComponent(q),{cacheTtl:3000}); const items=data.items||[]; state.householdSuggestions=items; host.innerHTML=items.length?items.map(item=>'<button type="button" class="list-group-item list-group-item-action" data-platform-action="livestock.selectHousehold" data-id="'+Number(item.id)+'"><div class="d-flex justify-content-between"><strong>'+esc(item.household_code)+'</strong><span class="badge text-bg-light">'+num(item.livestock_count)+' cơ sở</span></div><div>'+esc(item.head_citizen_name||'')+'</div><small class="text-muted">'+esc(item.address||'')+'</small></button>').join(''):'<div class="list-group-item text-muted">Không tìm thấy hộ phù hợp</div>'; host.classList.remove('d-none');}
function selectHousehold(item,keepDisabled=false){if(!item)return; state.selectedHousehold=item; const form=$('#livestockForm'); form.elements.household_id.value=item.id; $('#livestockHouseholdAutocomplete').value=item.household_code+' - '+(item.head_citizen_name||''); $('#livestockHouseholdAutocomplete').disabled=keepDisabled||false; $('#livestockHouseholdSelected').textContent=item.address||''; const owner=form.elements.owner_name; const location=form.elements.location; if(owner&&!owner.value)owner.value=item.head_citizen_name||''; if(location&&!location.value)location.value=item.address||''; hideSuggestions();}
function setForm(r){const form=$('#livestockForm'); selectHousehold({id:r.household_id,household_code:r.household_code,head_citizen_name:r.head_citizen_name,address:r.address},true); ensureSelectOption(form.elements.facility_type,r.facility_type,r.facility_type_label); const first=(r.groups&&r.groups[0])||{}; Object.entries({id:r.id,owner_name:r.owner_name,facility_name:r.facility_name,facility_type:r.facility_type,location:r.location,area_code:r.area_code,farming_area_m2:r.farming_area_m2,status:r.status,note:r.note,animal_type:first.animal_type,breed:first.breed,quantity:first.quantity,vaccine_date:first.vaccine_date,disease_status:first.disease_status,barn_area:first.barn_area}).forEach(([k,v])=>{const el=form.elements[k]; if(el)el.value=v??'';}); const vaccinated=form.elements.vaccinated; if(vaccinated&&vaccinated.type==='checkbox')vaccinated.checked=!!first.vaccinated; const groupHost=$('#livestockGroupRows'); if(groupHost)(r.groups&&r.groups.length?r.groups:[{animal_type:PIG,animal_group:'',quantity:0}]).forEach(addGroupRow);}
function ensureSelectOption(select,value,label){if(!select||!value)return; if(!Array.from(select.options).some(o=>String(o.value)===String(value))){const option=document.createElement('option'); option.value=value; option.textContent=label||value; select.appendChild(option);}}
function addGroupRow(group={}){const host=$('#livestockGroupRows'); if(!host)return; const idx=host.children.length; const row=document.createElement('div'); row.className='livestock-group-row border rounded p-2 mb-2'; row.innerHTML='<div class="row g-2 align-items-end"><input type="hidden" data-field="id" value="'+esc(group.id||'')+'"><div class="col-md-2"><label class="form-label">Loại vật nuôi</label><select class="form-select" data-field="animal_type" required>'+options(state.catalogs?.animal_types,group.animal_type||'')+'</select></div><div class="col-md-2 livestock-group-field"><label class="form-label livestock-group-label">Nhóm vật nuôi</label><select class="form-select" data-field="animal_group"></select></div><div class="col-md-2"><label class="form-label">Giống</label><input class="form-control" data-field="breed" value="'+esc(group.breed||'')+'"></div><div class="col-md-1"><label class="form-label">Số lượng</label><input class="form-control" data-field="quantity" type="number" min="0" step="1" value="'+Number(group.quantity||0)+'" required></div><div class="col-md-2"><label class="form-label">Khu chuồng</label><input class="form-control" data-field="barn_area" value="'+esc(group.barn_area||'')+'"></div><div class="col-md-1"><div class="form-check"><input class="form-check-input" type="checkbox" data-field="vaccinated" '+(group.vaccinated?'checked':'')+'><label class="form-check-label">Tiêm</label></div></div><div class="col-md-2"><label class="form-label">Ngày tiêm</label><input class="form-control" data-field="vaccine_date" type="date" value="'+esc(group.vaccine_date||'')+'"></div><div class="col-md-2"><label class="form-label">Dịch</label><select class="form-select" data-field="disease_status">'+options(state.catalogs?.disease_statuses,group.disease_status||'NONE')+'</select></div><div class="col-md-1 text-end"><button type="button" class="btn btn-outline-danger" data-platform-action="livestock.removeGroup" '+(idx===0?'disabled':'')+'><i class="fa-solid fa-trash"></i></button></div></div><div class="small text-muted livestock-vaccine-hint mt-1"></div><div class="mt-2"><input class="form-control" data-field="note" placeholder="Ghi chú nhóm vật nuôi" value="'+esc(group.note||'')+'"></div>'; host.appendChild(row); const type=row.querySelector('[data-field="animal_type"]'); type.addEventListener('change',()=>syncGroupRow(row,true)); syncGroupRow(row,false,group.animal_group||''); updateGroupRemoveButtons();}
function groupItemsFor(type,current=''){const items=state.catalogs?.animal_groups||[]; const allowed=type===PIG?PIG_GROUPS:(type===DOG?DOG_GROUPS:[]); const values=new Set(allowed); if(type===PIG&&PIG_LEGACY_GROUPS.includes(current))values.add(current); return items.filter(i=>values.has(String(i.value)));}
function syncGroupRow(row,clear=false,currentValue=''){const type=row.querySelector('[data-field="animal_type"]')?.value||''; const group=row.querySelector('[data-field="animal_group"]'); const field=row.querySelector('.livestock-group-field'); const label=row.querySelector('.livestock-group-label'); const hint=row.querySelector('.livestock-vaccine-hint'); const previous=clear?'':(currentValue||group.value||''); const needsGroup=type===PIG||type===DOG; field.classList.toggle('d-none',!needsGroup); group.disabled=!needsGroup; group.required=needsGroup; if(!needsGroup){group.innerHTML=''; group.value=''; if(hint)hint.textContent=''; return;} label.textContent=type===PIG?'Nhóm lợn (*)':'Mục đích nuôi (*)'; group.innerHTML=options(groupItemsFor(type,previous),previous); if(type===DOG&&hint)hint.textContent='Thông tin tiêm phòng phục vụ theo dõi phòng bệnh; hệ thống chỉ lưu trạng thái đã tiêm và ngày tiêm.'; else if(hint)hint.textContent='';}
function updateGroupRemoveButtons(){const rows=Array.from($('#livestockGroupRows')?.children||[]); rows.forEach((row,i)=>{const btn=row.querySelector('[data-platform-action="livestock.removeGroup"]'); if(btn)btn.disabled=rows.length===1&&i===0;});}
function options(items=[],value=''){return '<option value="">Chọn</option>'+(items||[]).map(i=>'<option value="'+esc(i.value)+'" '+(String(i.value)===String(value)?'selected':'')+'>'+esc(i.label||i.value)+'</option>').join('');}
function normalizeGroupForSubmit(obj){const type=obj.animal_type||''; if(type===PIG){if(!PIG_GROUPS.includes(obj.animal_group)&&!PIG_LEGACY_GROUPS.includes(obj.animal_group))throw new Error('Vui lòng chọn Nhóm lợn');} else if(type===DOG){if(!DOG_GROUPS.includes(obj.animal_group))throw new Error('Vui lòng chọn Mục đích nuôi chó');} else obj.animal_group=''; obj.quantity=Number(obj.quantity||0); return obj;}
function collectGroups(){const host=$('#livestockGroupRows'); if(host)return Array.from(host.children).map(row=>{const obj={}; row.querySelectorAll('[data-field]').forEach(el=>{obj[el.dataset.field]=el.type==='checkbox'?el.checked?1:0:el.value;}); return normalizeGroupForSubmit(obj);}).filter(g=>g.animal_type); const form=$('#livestockForm'); if(!form)return []; const value=name=>form.elements[name]?.value||''; const animalType=value('animal_type'); if(!animalType)return []; return [normalizeGroupForSubmit({animal_type:animalType,animal_group:value('animal_group'),breed:value('breed'),quantity:Number(value('quantity')||0),vaccinated:form.elements.vaccinated?.checked?1:0,vaccine_date:value('vaccine_date'),disease_status:value('disease_status')||'NONE',barn_area:value('barn_area'),note:value('note')})];}
async function save(e){e.preventDefault(); const form=e.currentTarget; const id=form.elements.id.value; if(!form.elements.facility_type?.value)return toast('Vui lòng chọn loại hình cơ sở','warning'); if(!form.elements.household_id.value)return toast('Vui lòng chọn hộ gia đình','warning'); let groups=[]; try{groups=collectGroups();}catch(err){return toast(err.message,'warning');} if(!groups.length)return toast('Cần nhập ít nhất một nhóm vật nuôi','warning'); const payload=Object.fromEntries(new FormData(form).entries()); payload.groups=groups; delete payload.id; try{const saved=await request(id?API+'/'+encodeURIComponent(id):API,{method:id?'PUT':'POST',body:payload}); closeModal('livestockModal'); toast('Đã lưu cơ sở chăn nuôi'); load(); if(state.currentHouseholdId&&Number(saved.household_id)===state.currentHouseholdId)renderHouseholdLivestock(state.currentHouseholdId); if(state.drawerHousehold&&Number(saved.household_id)===Number(state.drawerHousehold.id))openDrawer(saved.household_id);}catch(err){toast(err.message,'danger');}}
async function remove(id){if(!can('livestock','delete'))return toast('Tài khoản hiện tại không có quyền xóa','warning'); if(!window.confirm?.('Xóa cơ sở chăn nuôi này?'))return; try{const before=await request(API+'/'+encodeURIComponent(id)); await request(API+'/'+encodeURIComponent(id),{method:'DELETE'}); toast('Đã xóa cơ sở chăn nuôi'); load(); if(state.currentHouseholdId&&Number(before.household_id)===state.currentHouseholdId)renderHouseholdLivestock(state.currentHouseholdId);}catch(e){toast(e.message,'danger');}}
async function openDrawer(householdId){const body=$('#livestockDrawerBody'); if(!body)return; openModal('livestockHouseholdModal'); body.innerHTML='<div class="livestock-profile-loading">'+labels.loading+'</div>'; try{const [household,livestock]=await Promise.all([request('/api/households/'+encodeURIComponent(householdId),{cacheTtl:3000}),request(API+'/household/'+encodeURIComponent(householdId),{cacheTtl:0})]); state.drawerHousehold=household; $('#livestockDrawerTitle').textContent=(household.household_code||'')+' - '+(household.head_citizen_name||''); $('#livestockDrawerSubtitle').textContent=household.address||''; body.innerHTML=drawerHtml(household,livestock.items||[]);}catch(e){body.innerHTML='<div class="alert alert-danger">'+esc(e.message)+'</div>';}}
function drawerHtml(household,items){return '<section class="livestock-profile-section is-priority"><div class="livestock-section-title-row"><h4><i class="fa-solid fa-paw"></i> CHĂN NUÔI</h4>'+(can('livestock','create')?'<button class="btn btn-sm btn-success" type="button" data-platform-action="livestock.create" data-household-id="'+Number(household.id||0)+'" data-household-code="'+esc(household.household_code||'')+'" data-head-citizen-name="'+esc(household.head_citizen_name||'')+'" data-address="'+esc(household.address||'')+'"><i class="fa-solid fa-plus"></i> Thêm cơ sở</button>':'')+'</div>'+facilityTable(items)+'</section>';}
function facilityTable(items){if(!items.length)return '<div class="livestock-empty">Hộ này chưa có dữ liệu chăn nuôi.</div>'; return '<div class="table-responsive"><table class="table table-sm livestock-inner-table"><thead><tr><th>Loại hình</th><th>Tên</th><th>Nhóm vật nuôi</th><th>Tổng đàn</th><th>Trạng thái</th><th class="text-end">Thao tác</th></tr></thead><tbody>'+items.map(r=>'<tr><td>'+esc(r.facility_type_label)+'</td><td>'+esc(r.facility_name||r.owner_name||'')+'</td><td>'+esc(r.group_summary||r.animal_summary||'')+'</td><td><strong>'+num(r.total_quantity)+'</strong> con</td><td>'+esc(r.status_label)+'</td><td class="text-end"><button class="btn btn-sm btn-outline-primary" type="button" data-platform-action="livestock.edit" data-id="'+Number(r.id)+'">Sửa</button></td></tr>').join('')+'</tbody></table></div>';}
async function renderHouseholdLivestock(householdId){const host=$('#householdLivestockTabBody'); if(!host)return; state.currentHouseholdId=Number(householdId||0); try{const data=await request(API+'/household/'+encodeURIComponent(householdId),{cacheTtl:0}); host.innerHTML='<div class="d-flex justify-content-between align-items-center mb-2"><h6 class="mb-0">CHĂN NUÔI</h6>'+(can('livestock','create')?'<button class="btn btn-sm btn-primary" type="button" data-platform-action="livestock.create" data-household-id="'+Number(householdId||0)+'" data-household-code="'+esc(host.dataset.code||'')+'" data-head-citizen-name="'+esc(host.dataset.head||'')+'" data-address="'+esc(host.dataset.address||'')+'"><i class="fa-solid fa-plus"></i> Thêm cơ sở</button>':'')+'</div>'+facilityTable(data.items||[]);}catch(e){host.innerHTML='<div class="alert alert-danger mb-0">'+esc(e.message)+'</div>';}}
function installHouseholdDetailHook(){ if(typeof window.showHousehold!=='function'||window.showHousehold.__livestockHooked)return; const original=window.showHousehold; const wrapped=async function(id){ await original.apply(this,arguments); const body=$('#detailBody'); if(!body||body.querySelector('#householdLivestockTabBody'))return; let household={id}; try{household=await request('/api/households/'+encodeURIComponent(id),{cacheTtl:5000});}catch(e){} const section=document.createElement('section'); section.className='content-card mt-3 household-livestock-section'; section.innerHTML='<div id="householdLivestockTabBody" data-code="'+esc(household.household_code||'')+'" data-head="'+esc(household.head_citizen_name||'')+'" data-address="'+esc(household.address||'')+'"><div class="text-muted">Đang tải chăn nuôi...</div></div>'; body.appendChild(section); renderHouseholdLivestock(id); }; wrapped.__livestockHooked=true; window.showHousehold=wrapped; }
function hideSuggestions(){ $('#livestockHouseholdSuggestions')?.classList.add('d-none'); }
window.loadLivestock=load; window.openLivestockForm=openForm; window.deleteLivestock=remove; window.renderHouseholdLivestock=renderHouseholdLivestock; window.openLivestockHouseholdDrawer=openDrawer;
})();
